import type { Car, ImageStatus } from "./types";

// Image paths per car slug (public/cars/{slug}/). GENERATED by tools/ingest-car-images.mjs:
// don't edit by hand, re-run the tool. Empty slots fall back to the line-art illustration in
// CarArt. Later this moves to the CMS.

export interface CarMedia {
  status: ImageStatus;
  hero?: string;
  side?: string;
  card?: string;
  cockpit?: string;
  gallery?: { src: string; alt: string }[];
}

export const carMedia: Record<string, CarMedia | undefined> = {};

/** The car's image status: from its generated media when present, else the data default. */
export const imageStatus = (car: Car): ImageStatus => carMedia[car.slug]?.status ?? car.images.status;
